/// previous, unchecked, behavior use
/// `size_prefixed_root_as_job_unchecked`.
pub fn size_prefixed_root_as_job(buf: &[u8]) -> Result<Job, flatbuffers::InvalidFlatbuffer> {
    flatbuffers::size_prefixed_root::<Job>(buf)
}
#[inline]
/// Verifies, with the given options, that a buffer of bytes
/// contains a `Job` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_job_unchecked`.
pub fn root_as_job_with_opts<'b, 'o>(
    opts: &'o flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<Job<'b>, flatbuffers::InvalidFlatbuffer> {
    flatbuffers::root_with_opts::<Job<'b>>(opts, buf)
}
#[inline]
/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `Job` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_job_unchecked`.
pub fn size_prefixed_root_as_job_with_opts<'b, 'o>(
    opts: &'o flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<Job<'b>, flatbuffers::InvalidFlatbuffer> {
    flatbuffers::size_prefixed_root_with_opts::<Job<'b>>(opts, buf)
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a Job and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `Job`.
pub unsafe fn root_as_job_unchecked(buf: &[u8]) -> Job {
    flatbuffers::root_unchecked::<Job>(buf)
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a size prefixed Job and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `Job`.
pub unsafe fn size_prefixed_root_as_job_unchecked(buf: &[u8]) -> Job {
    flatbuffers::size_prefixed_root_unchecked::<Job>(buf)
}
#[inline]
pub fn finish_job_buffer<'a, 'b>(
    fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>,
    root: flatbuffers::WIPOffset<Job<'a>>,
) {
    fbb.finish(root, None);
}

#[inline]
pub fn finish_size_prefixed_job_buffer<'a, 'b>(
    fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>,
    root: flatbuffers::WIPOffset<Job<'a>>,
) {
    fbb.finish_size_prefixed(root, None);
}
